                .map(p -> PersonResponse.from(p, byPerson.getOrDefault(p.getId(), List.of()),
                        patronsOf.getOrDefault(p.getId(), List.of()),
                        new PersonGrades(p.getGrade(), gradesOf.getOrDefault(p.getId(), List.of())), view.getToday()))
                .toList());
